/// <summary>
/// MPJ_10886 Accounting source explorer
/// </summary>
[ExtensionOf(classStr(AccountingSourceExplorerProcessor))]
final class METAccountingSourceExplorerProcessor_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_10886 Accounting source explorer COC of run method to update the temp table fields.
    /// </summary>
    protected void run()
    {
        
        next run();
        this.metupadteFiscalCalendarYear();
        this.metupadteFiscalCalendarPeriod();
        this.metupdatedueDateForCustTrans();
        this.metupdatedueDateForVendTrans();
        this.metmodifiedBy();
        this.metProjectRelatedInfo();
        this.metOffsetAccount();
        this.metProfitCenterDimensionName();
        this.metCostCenterDimensionName();
        this.metLedgerJournalCreatedDateTime();
        this.metUpdateDocumentNumFromCustTrans();
        this.metUpdateDocumentNumFromVendTrans();

    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer 
    /// </summary>
    private void metupadteFiscalCalendarYear()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        GeneralJournalEntry             metgeneralJournalEntry;
        FiscalCalendarYear              metfiscalCalendaryear;
        

        update_recordset metaccountingSourceExplorerTmp
            setting METFiscalYearName = metfiscalCalendaryear.Name
            join TableId from metgeneralJournalEntry
                where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
                &&    metgeneralJournalEntry.SubledgerVoucherDataAreaId == curExt()
            join RecId,Name from metfiscalCalendaryear
                where metfiscalCalendaryear.RecId == metgeneralJournalEntry.FiscalCalendarYear;
    }

    /// <summary>
    /// Update Period name
    /// </summary>
    private void metupadteFiscalCalendarPeriod()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        GeneralJournalEntry             metgeneralJournalEntry;
        FiscalCalendarPeriod            metFiscalCalendarPeriod;

        update_recordset metaccountingSourceExplorerTmp
            setting METFiscalPeriodName = metFiscalCalendarPeriod.Name
            join TableId from metgeneralJournalEntry
                where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
                &&    metgeneralJournalEntry.SubledgerVoucherDataAreaId == curExt()
            join Name from metFiscalCalendarPeriod
                where metFiscalCalendarPeriod.RecId == metgeneralJournalEntry.FiscalCalendarPeriod;
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer
    /// </summary>
    private void metupdatedueDateForCustTrans()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        CustTrans                       metcustTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METClosed = metcustTrans.Closed,
                    METDueDate = metcustTrans.DueDate,
                    METLastSettleVoucher = metcustTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher 
            from metcustTrans
                where metcustTrans.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
                   && metcustTrans.TransDate == metaccountingSourceExplorerTmp.AccountingDate
                   && metcustTrans.Invoice != '';
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer
    /// </summary>
    private void metupdatedueDateForVendTrans()
    {
        AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp();
        VendTrans                       metvendTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METClosed = metvendTrans.Closed,
                    METDueDate = metvendTrans.DueDate,
                    METLastSettleVoucher = metvendTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher from metvendTrans
                where metvendTrans.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
                   && metvendTrans.TransDate == metaccountingSourceExplorerTmp.AccountingDate
                   && metvendTrans.Invoice != '';
    }

    /// <summary>
    /// MPJ_10886 Accounting source explorer journal created by 
    /// </summary>
    private void metmodifiedBy()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        GeneralJournalEntry                 metgeneralJournalEntry;
        LedgerEntryJournal                  metledgerentryjournal;
        LedgerJournalTable                  metledgerjournaltable;
        
        update_recordset metaccountingSourceExplorerTmp
            setting METModifiedBy = metledgerjournaltable.CreatedBy
                join TableId from metgeneralJournalEntry
            where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
            &&    metgeneralJournalEntry.SubledgerVoucherDataAreaId == curExt()
                join TableId from metledgerentryjournal
            where metledgerentryjournal.RecId == metgeneralJournalEntry.LedgerEntryJournal
                join TableId,CreatedBy from metledgerjournaltable
            where metledgerjournaltable.JournalNum == metledgerentryjournal.JournalNumber;

    }

/// <summary>
/// Update Project related information
/// </summary>
private void metProjectRelatedInfo()
{
    AccountingSourceExplorerTmp     metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
    ProjTransPosting                metProjTransPosting;
    ProjPostTransView               metProjPostTransView;
    
    update_recordSet metaccountingSourceExplorerTmp
        setting ProjectActivityNumber   = metProjPostTransView.ActivityNumber,
                ProjectLinePropertyId   = metProjPostTransView.LinePropertyId,
                ProjectCategoryId       = metProjPostTransView.CategoryId
    join ActivityNumber, CategoryId, LinePropertyId
        from metProjPostTransView
        where metProjPostTransView.ProjId   == metaccountingSourceExplorerTmp.ProjectId
        join TableId from metProjTransPosting
        where metProjTransPosting.TransId   == metProjPostTransView.TransId
            && metProjTransPosting.ProjId   == metProjPostTransView.ProjId
            && metProjTransPosting.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
            && metaccountingSourceExplorerTmp.ProjectId != ''
            && (metaccountingSourceExplorerTmp.ProjectCategoryId == ''
                || metaccountingSourceExplorerTmp.ProjectActivityNumber == ''
                || metaccountingSourceExplorerTmp.ProjectLinePropertyId == '');
        
}

    /// <summary>
    /// MPJ_10886 Accounting source explorer 
    /// </summary>
    private void metOffsetAccount()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        GeneralJournalEntry                 metgeneralJournalEntry;
        LedgerEntryJournal                  metledgerentryjournal;
        LedgerJournalTable                  metledgerjournaltable;
        LedgerJournalTrans                  metledgerjournaltrans;
        DimensionAttributeValueCombination metDimensionAttributeValueCombination;

        update_recordSet metaccountingSourceExplorerTmp
            setting METOffsetAccount = metDimensionAttributeValueCombination.DisplayValue
                join TableId from metgeneralJournalEntry
            where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
            &&    metgeneralJournalEntry.SubledgerVoucherDataAreaId == curExt()
                join TableId from metledgerentryjournal
            where metledgerentryjournal.RecId == metgeneralJournalEntry.LedgerEntryJournal
                join TableId from metledgerjournaltable
            where metledgerjournaltable.JournalNum == metledgerentryjournal.JournalNumber
            &&    metledgerjournaltable.Posted     == NoYes::Yes
                join TableId from metledgerjournaltrans
            where metledgerjournaltrans.JournalNum == metledgerjournaltable.JournalNum
            &&    metledgerjournaltrans.OffsetAccountType == LedgerJournalACType::Ledger
                join DisplayValue,RecId from metDimensionAttributeValueCombination
            where metDimensionAttributeValueCombination.RecId == metledgerjournaltrans.OffsetLedgerDimension;

    }

    /// <summary>
    /// Updates invoice id from the customer invoice transactions
    /// </summary>
    private void metUpdateDocumentNumFromCustTrans()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        CustTrans                           custTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METInvoiceNumber = custTrans.Invoice
            where metaccountingSourceExplorerTmp.METInvoiceNumber == ''
        join Voucher, TransDate, Invoice, DocumentDate from custTrans
            where custTrans.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
               && custTrans.TransDate == metaccountingSourceExplorerTmp.AccountingDate
               && custTrans.DocumentNum != '';

   
    }

    /// <summary>
    /// Updates invoice id from the vendor invoice transactions
    /// </summary>
    private void metUpdateDocumentNumFromVendTrans()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        VendTrans                           vendTrans;

        update_recordSet metaccountingSourceExplorerTmp
            setting METInvoiceNumber = vendTrans.Invoice
            where metaccountingSourceExplorerTmp.METInvoiceNumber == ''
        join Voucher, TransDate, Invoice, DocumentDate from vendTrans
            where vendTrans.Voucher == metaccountingSourceExplorerTmp.SubledgerVoucher
               && vendTrans.TransDate == metaccountingSourceExplorerTmp.AccountingDate
               && vendTrans.DocumentNum != '';

   
    }

    /// <summary>
    /// Updates ASE with the ledger journal create date and time
    /// </summary>
    private void metLedgerJournalCreatedDateTime()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        GeneralJournalEntry                 metgeneralJournalEntry;
        LedgerEntryJournal                  metledgerentryjournal;
        LedgerJournalTable                  metledgerjournaltable;

        update_recordSet metaccountingSourceExplorerTmp
            setting METLedgerJournalCreatedDateTime = metledgerjournaltable.createdDateTime
                join TableId from metgeneralJournalEntry
            where metgeneralJournalEntry.JournalNumber == metaccountingSourceExplorerTmp.JournalNumber
            &&    metgeneralJournalEntry.SubledgerVoucherDataAreaId == curExt()
                join TableId from metledgerentryjournal
            where metledgerentryjournal.RecId == metgeneralJournalEntry.LedgerEntryJournal
                join TableId, createdDateTime from metledgerjournaltable
            where metledgerjournaltable.JournalNum == metledgerentryjournal.JournalNumber;

    }

    private void metProfitCenterDimensionName()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        DimensionAttribute                  metDimensionAttribute;
        DimensionFinancialTag               metDimensionFinancialTag;  
        DimensionAttributeLevelValueView    metDimAttributeLevelValueView;

        metDimensionAttribute = DimensionAttribute::findByName(METConstants::profitCentre);
        
        update_recordSet metaccountingSourceExplorerTmp
            setting METProfitCentreName = metDimensionFinancialTag.Description
                join ValueCombinationRecId, DimensionAttribute, DisplayValue from metDimAttributeLevelValueView
        where   metDimAttributeLevelValueView.ValueCombinationRecId == metaccountingSourceExplorerTmp.LedgerDimension
        &&      metDimAttributeLevelValueView.DimensionAttribute == metDimensionAttribute.RecId
            join Value,Description from metDimensionFinancialTag
        where   metDimensionFinancialTag.Value == metDimAttributeLevelValueView.DisplayValue;

    }

    private void metCostCenterDimensionName()
    {
        AccountingSourceExplorerTmp         metaccountingSourceExplorerTmp = this.parmAccountingSourceExplorerTmp() ;
        DimensionAttribute                  metDimensionAttribute ;
        DimensionAttributeValueSetItemView  metDimensionAttributeValueSetItemView;
        DimensionAttributeValue             metDimensionAttributeValue;
        DimensionFinancialTag               metDimensionFinancialTag;
        DimensionAttributeLevelValueView    metDimAttributeLevelValueView;

        metDimensionAttribute = DimensionAttribute::findByName(METConstants::costCenter);
        
        update_recordSet metaccountingSourceExplorerTmp
            setting METCostCentreName = metDimensionFinancialTag.Description
                join ValueCombinationRecId, DimensionAttribute, DisplayValue from metDimAttributeLevelValueView
        where   metDimAttributeLevelValueView.ValueCombinationRecId == metaccountingSourceExplorerTmp.LedgerDimension
        &&      metDimAttributeLevelValueView.DimensionAttribute == metDimensionAttribute.RecId
            join Value,Description from metDimensionFinancialTag
        where   metDimensionFinancialTag.Value == metDimAttributeLevelValueView.DisplayValue;

    }
